#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MiniCut Patch 46 - Spill looks the same on and off, faster spill and compound clips

* Spill outside the media: the picture INSIDE the media looks the same with the switch on or off. Measured on all 175 effects: before, 81 looked different (size, timing of a wipe ...); now 0. The 3D objects (Cube, Card, Sphere, Cylinder) size themselves from the media and wrap the media itself, so with spill on they really draw outside the media at the size you set.
* 56 effects always stay inside the media (they size themselves from the whole layer and could not be made equal), their card has no Spill switch: antifisheye, area_blur, bend, bitdepth, blockdissolve, bounce, breakwipe, checkwipe, circlewipe, crt, crystallize, deadgpu, fadenoise, fbmfade, feather, fisheye, fluidcurl, fluidwarp, fractalwarp, glitch, grain, lensdist, lensdistrgb, lensorb, liquidwave, liquidwipe, melting, noiseglitch, noiseover, offsetglitch, opticcomp, pinch, pixelglitch, polar, psykoblobs, randompattern, refraction, repgrid, reppath, repscatter, rgbglitch, scatterglitch, shatter, sliceglitch, squarebreak, squeeze, swing, swirl, tiles, turbdisp, twist, vcr, vhsnoise, vignette, waterwave, zoomblur.
* Faster: the spill layer is about the size of the picture frame at most (it was up to 2.5 times), and the adaptive effect resolution reaches its budget in a few frames instead of walking down step by step.
* Compound clips with alpha: a tiny test render first (6 % of a frame) and the second full render only when something is transparent. A fully opaque compound costs 1.1 renders instead of 2.

Files changed: minicut/render/effects.py, minicut/render/fxpack/kit.py, minicut/render/fxpack/particle.py, minicut/render/renderer.py, minicut/workspace/effects_panel.py
  python Patch/apply_46_spill_fps_compound.py --check      (look only, change nothing)
  python Patch/apply_46_spill_fps_compound.py              (install)
  python Patch/apply_46_spill_fps_compound.py --revert     (put the files back from the backup)
Close MiniCut before installing. The MiniCut Launcher can do all of this for you.
"""
import base64, datetime, hashlib, json, os, py_compile, shutil, sys, zlib
PATCH_NAME = "patch46_spill_equal"
REPLACE = {'minicut/render/effects.py': {'base': '7436510fffc377cdd6e8d7ca916534fc786c933c018462745ce776a2e042ceba', 'new': '2a4cf337c24d5183d08a7ecf24ed6e23d48757a1921e5c1be194536a9ef3402b'}, 'minicut/render/fxpack/kit.py': {'base': '1e51c29cefdf54a77ec6aedd420c58e5418115a292e6ad51772870c710bd2bb6', 'new': '22f8a9bb92f5e104c36fbb1c065a26b2faba38e7891c81ec12ae2a2a9a5c7ece'}, 'minicut/render/fxpack/particle.py': {'base': '6655e96291b7fc84c51bfe8d386d4d4636790817616f660433471d7e14f05608', 'new': '0e6cd6868c3cf28dc3f219bad4f59a20322e6796351e30cce21edaf6dc5a2b84'}, 'minicut/render/renderer.py': {'base': 'd7ca7819bd7d1e8db03746aec80b37d1bf7d5b9b8b913c06386ad16358738dfd', 'new': '91433c6339f68722c1596955380625f061ceaa6557061a04ed222ba9be2b43d3'}, 'minicut/workspace/effects_panel.py': {'base': '05f21c11934ac86de080629c56f08d25332dceab646cb68ecad2cd566cfd26f9', 'new': '8576667ae1337a5793384c1302df76bad2bec974f75a81c43efeb8166c88e441'}}
NEW_FILES = {}
PAYLOAD = {'minicut/render/effects.py': '', 'minicut/render/fxpack/kit.py': '', 'minicut/render/fxpack/particle.py': '', 'minicut/render/renderer.py': '', 'minicut/workspace/effects_panel.py': ''}
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = HERE if os.path.isfile(os.path.join(HERE, "minicut", "app.py")) else (os.path.dirname(HERE) if os.path.isfile(os.path.join(os.path.dirname(HERE), "minicut", "app.py")) else HERE)
BACKUP_ROOT = os.path.join(ROOT, "_patch_backup")


def norm_hash(b): return hashlib.sha256(b.replace(b"\r\n", b"\n")).hexdigest()
def path_of(rel): return os.path.join(ROOT, *rel.split("/"))
def read(rel):
    try:
        with open(path_of(rel), "rb") as f: return f.read()
    except OSError: return None
def new_bytes(rel):
    return zlib.decompress(base64.b64decode(PAYLOAD[rel]))
def latest_backup():
    found = []
    if os.path.isdir(BACKUP_ROOT):
        for d in os.listdir(BACKUP_ROOT):
            mf = os.path.join(BACKUP_ROOT, d, "MANIFEST.json")
            if os.path.isfile(mf):
                try:
                    with open(mf, encoding="utf-8") as f:
                        if json.load(f).get("patch") == PATCH_NAME: found.append(d)
                except Exception: pass
    return os.path.join(BACKUP_ROOT, sorted(found)[-1]) if found else None


def revert():
    bdir = latest_backup()
    if not bdir: print("No backup of this update was found."); return 1
    with open(os.path.join(bdir, "MANIFEST.json"), encoding="utf-8") as f: m = json.load(f)
    for rel in m.get("replaced", []): shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
    for rel in m.get("created", []):
        try: os.remove(path_of(rel))
        except OSError: pass
    os.replace(os.path.join(bdir, "MANIFEST.json"), os.path.join(bdir, "MANIFEST.undone.json"))
    print("Reverted from backup:", bdir); return 0


def main():
    if not os.path.isfile(os.path.join(ROOT, "minicut", "app.py")):
        print("ERROR: the MiniCut folder was not found. Put this file in MiniCut/Patch/ (or next to the minicut folder)."); return 2
    if "--revert" in sys.argv: return revert()
    todo_replace, todo_new, already = [], [], 0
    for rel, h in REPLACE.items():
        cur = read(rel)
        if cur is None: print("STOPPED: missing file", rel, "- no files were changed."); return 3
        c = norm_hash(cur)
        if c == h["new"]: already += 1
        elif c == h["base"]: todo_replace.append(rel)
        else:
            print("STOPPED:", rel, "is not the version this update expects (it was changed by hand or by another update).")
            print("No files were changed. This protects your own edits."); return 3
    for rel, text in NEW_FILES.items():
        cur = read(rel)
        if cur is None: todo_new.append(rel)
        elif norm_hash(cur) == norm_hash(text.encode("utf-8")): already += 1
        else: print("STOPPED:", rel, "already exists with other content. No files were changed."); return 3
    if not todo_replace and not todo_new: print("This update is already installed."); return 0
    if "--check" in sys.argv:
        print("Check passed. Would change:", ", ".join(todo_replace + todo_new)); return 0
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S"); bdir = os.path.join(BACKUP_ROOT, stamp); k = 1
    while os.path.exists(bdir): k += 1; bdir = os.path.join(BACKUP_ROOT, "%s_%d" % (stamp, k))      # two installs in one second
    os.makedirs(bdir, exist_ok=False)
    for rel in todo_replace:
        dst = os.path.join(bdir, *rel.split("/")); os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy2(path_of(rel), dst)
    with open(os.path.join(bdir, "MANIFEST.json"), "w", encoding="utf-8") as f:
        json.dump({"patch": PATCH_NAME, "created": todo_new, "replaced": todo_replace}, f, indent=2)
    try:
        for rel in todo_replace:
            cur = read(rel); data = new_bytes(rel).replace(b"\r\n", b"\n")
            if b"\r\n" in cur: data = data.replace(b"\n", b"\r\n")            # keep the file's own line endings
            with open(path_of(rel), "wb") as f: f.write(data)
            if norm_hash(read(rel)) != REPLACE[rel]["new"]: raise RuntimeError("hash mismatch after writing " + rel)
        for rel in todo_new:
            os.makedirs(os.path.dirname(path_of(rel)), exist_ok=True)
            with open(path_of(rel), "wb") as f: f.write(NEW_FILES[rel].encode("utf-8"))
        for rel in todo_replace + todo_new:
            if rel.endswith(".py"): py_compile.compile(path_of(rel), doraise=True)
    except Exception as ex:
        for rel in todo_replace: shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
        for rel in todo_new:
            try: os.remove(path_of(rel))
            except OSError: pass
        print("ERROR: the update failed and every file was put back:", repr(ex)); return 1
    print("Installed Patch 46. Changed:", ", ".join(todo_replace + todo_new)); print("Backup:", bdir); return 0


if __name__ == "__main__":
    try: code = main()
    except Exception as ex: print("Unexpected error:", repr(ex)); code = 1
    sys.exit(code)
